            j+=1; continue
        if a=='--colors':
            if j+1>=len(args) or args[j+1]=='' or args[j+1].startswith('-'):
                return color_error(missing=True)
            if args[j+1] not in ('auto','always','never'):
                return color_error(args[j+1])
            j+=2; continue
        if a.startswith('--colors='):
            value=a.split('=',1)[1]
            if value == '':
                return color_error(missing=True)
            if value not in ('auto','always','never'):
                return color_error(value)
            j+=1; continue
        break
    if j<len(args) and args[j] in ('--version','-V'):
        print('taplo 0.10.0')
