                    'get','toml-test','completions','help'}
    if j<len(args) and not args[j].startswith('-') and args[j] not in known_commands:
        sys.stderr.write(f"error: unrecognized subcommand '{args[j]}'\n\nUsage: taplo [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n")
        return 2
