        if value == '':
            sys.stderr.write("error: a value is required for '--colors <COLORS>' but none was supplied\n  [possible values: auto, always, never]\n\nFor more information, try '--help'.\n")
            return 2
        if value not in ('auto', 'always', 'never'):
